    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which of the following is the most common chromosomal abnormality in live-born infants?', '["Trisomy 13", "Trisomy 18", "Trisomy 21", "Turner Syndrome"]', 2, 'Trisomy 21 (Down Syndrome) occurs in approximately 1 in 700 births.'),
    (v_topic_id, '2: A newborn presents with microcephaly, microphthalmia, polydactyly, and a cleft lip/palate. What is the most likely diagnosis?', '["Trisomy 21", "Trisomy 18", "Trisomy 13", "Wolf-Hirschhorn Syndrome"]', 2, 'Trisomy 13 (Patau Syndrome) is characterized by the "midline" defects mentioned.'),
    (v_topic_id, '3: Which chromosomal abnormality is characterized by "rocker-bottom" feet, clenched fists with overlapping fingers, and a prominent occiput?', '["Trisomy 13", "Trisomy 18", "Trisomy 21", "Cri-du-chat Syndrome"]', 1, 'Trisomy 18 (Edwards Syndrome) classic triad includes rocker-bottom feet, overlapping fingers, and micrognathia.'),
    (v_topic_id, '4: A 15-year-old girl presents with short stature, a webbed neck, and primary amenorrhea. What is the most likely karyotype?', '["47,XXY", "45,X", "47,XXX", "46,XY"]', 1, 'Turner Syndrome (45,X) is the most common cause of primary amenorrhea in females.'),
    (v_topic_id, '5: Which of the following is the most common cardiac defect associated with Down Syndrome?', '["Ventricular Septal Defect (VSD)", "Atrioventricular Septal Defect (AVSD)", "Atrial Septal Defect (ASD)", "Tetralogy of Fallot"]', 1, 'Endocardial cushion defects (AVSD) are found in about 40% of children with Down Syndrome.'),
    (v_topic_id, '6: A 2-year-old child with Down Syndrome presents with new-onset gait instability and neck pain. What should be suspected?', '["Leukemia", "Hypothyroidism", "Atlantoaxial instability", "Duodenal atresia"]', 2, 'Laxity of the transverse ligament of the atlas can lead to spinal cord compression.'),
    (v_topic_id, '7: Which of the following is an increased risk for children with Down Syndrome as they age?', '["Acute Lymphoblastic Leukemia (ALL)", "Alzheimer disease", "Hypothyroidism", "All of the above"]', 3, 'Down syndrome increases risk for ALL (and AML M7), early-onset Alzheimer, and autoimmune thyroiditis.'),
    (v_topic_id, '8: A neonate presents with a high-pitched, "cat-like" cry, microcephaly, and severe intellectual disability. Which deletion is likely present?', '["4p-", "5p-", "22q11.2", "7q11.2"]', 1, 'Cri-du-chat syndrome is caused by a deletion on the short arm of chromosome 5.'),
    (v_topic_id, '9: Which syndrome is characterized by the triad of "CATCH-22": Cardiac defects, Abnormal facies, Thymic hypoplasia, Cleft palate, and Hypocalcemia?', '["Williams Syndrome", "DiGeorge Syndrome", "Noonan Syndrome", "Prader-Willi Syndrome"]', 1, 'DiGeorge syndrome is a 22q11.2 microdeletion syndrome affecting the 3rd and 4th pharyngeal pouches.'),
    (v_topic_id, '10: A child with DiGeorge syndrome is at high risk for which type of infection due to thymic hypoplasia?', '["Bacterial", "Viral and Fungal", "Parasitic", "No increased risk"]', 1, 'T-cell deficiency leads to increased susceptibility to intracellular pathogens.'),
    (v_topic_id, '11: Which syndrome is characterized by "elfin" facies, extreme friendliness (cocktail party personality), and idiopathic hypercalcemia?', '["Williams Syndrome", "DiGeorge Syndrome", "Angelman Syndrome", "Fragile X Syndrome"]', 0, 'Williams syndrome is caused by a microdeletion on chromosome 7 (including the elastin gene).'),
    (v_topic_id, '12: What is the most common vascular abnormality seen in Williams Syndrome?', '["Coarctation of the aorta", "Supravalvular aortic stenosis", "Patent ductus arteriosus", "Pulmonary stenosis"]', 1, 'Elastin gene deletion leads to connective tissue issues, classically supravalvular aortic stenosis.'),
    (v_topic_id, '13: A child presents with severe hypotonia in infancy, followed by insatiable hunger (hyperphagia) and obesity in childhood. What is the diagnosis?', '["Prader-Willi Syndrome", "Angelman Syndrome", "Beckwith-Wiedemann Syndrome", "Alström Syndrome"]', 0, 'Prader-Willi is caused by loss of paternal expression on chromosome 15 (deletion or uniparental disomy).'),
    (v_topic_id, '14: Which syndrome is characterized by "happy puppet" behavior, jerky movements, frequent laughter, and severe intellectual disability?', '["Prader-Willi Syndrome", "Angelman Syndrome", "Fragile X Syndrome", "Rett Syndrome"]', 1, 'Angelman syndrome is caused by loss of maternal expression of the UBE3A gene on chromosome 15.'),
    (v_topic_id, '15: What is the most common inherited cause of intellectual disability in males?', '["Down Syndrome", "Fragile X Syndrome", "Klinefelter Syndrome", "Phenylketonuria"]', 1, 'Fragile X is an X-linked dominant condition with trinucleotide repeat expansion (CGG).'),
    (v_topic_id, '16: Which physical features are classic for Fragile X Syndrome in post-pubertal males?', '["Short stature and obesity", "Macro-orchidism, large ears, and a long face", "Micropenis and gynecomastia", "Webbed neck and shield chest"]', 1, 'Macro-orchidism is a hallmark sign after puberty.'),
    (v_topic_id, '17: Klinefelter Syndrome (47,XXY) is most often diagnosed at what age?', '["Birth", "Infancy", "Puberty", "Old age"]', 2, 'It often presents as failure of secondary sexual development or infertility.'),
    (v_topic_id, '18: Which of the following is a feature of Klinefelter Syndrome?', '["Short stature", "Small, firm testes and gynecomastia", "Increased risk of prostate cancer", "Precocious puberty"]', 1, 'Low testosterone and elevated gonadotropins lead to small testes and feminization.'),
    (v_topic_id, '19: A neonate is born with a large tongue (macroglossia), omphalocele, and hemihyperplasia. What is the most likely diagnosis?', '["Down Syndrome", "Beckwith-Wiedemann Syndrome", "Noonan Syndrome", "Cornelia de Lange Syndrome"]', 1, 'BWS is an overgrowth syndrome associated with genomic imprinting on chromosome 11.'),
    (v_topic_id, '20: Children with Beckwith-Wiedemann Syndrome require serial screening for which tumors?', '["Neuroblastoma and ALL", "Wilms tumor and Hepatoblastoma", "Retinoblastoma", "Brain tumors"]', 1, 'Abdominal ultrasound and alpha-fetoprotein (AFP) are used for screening until age 8.'),
    (v_topic_id, '21: Which syndrome is sometimes called the "male version of Turner Syndrome" because of features like short stature and webbed neck?', '["Klinefelter Syndrome", "Noonan Syndrome", "Marfan Syndrome", "Achondroplasia"]', 1, 'Noonan syndrome is autosomal dominant and can affect both males and females.'),
    (v_topic_id, '22: What is the most common cardiac defect in Noonan Syndrome?', '["Pulmonic stenosis", "Aortic stenosis", "VSD", "Coarctation of the aorta"]', 0, 'Pulmonic valve dysplasia/stenosis is the most frequent cardiac finding.'),
    (v_topic_id, '23: A tall adolescent male with long limbs, arachnodactyly, and pectus excavatum is found to have "ectopia lentis" (upward lens dislocation). Diagnosis?', '["Marfan Syndrome", "Homocystinuria", "Ehlers-Danlos Syndrome", "Osteogenesis Imperfecta"]', 0, 'Marfan syndrome involves a mutation in the fibrillin-1 gene (FBN1).'),
    (v_topic_id, '24: A child with Marfan-like features, intellectual disability, and "downward" lens dislocation most likely has:', '["Marfan Syndrome", "Homocystinuria", "Scurvy", "Rickets"]', 1, 'Homocystinuria is an AR metabolic disorder that mimics Marfan but includes thrombosis and ID.'),
    (v_topic_id, '25: What is the major cause of mortality in patients with Marfan Syndrome?', '["Retinal detachment", "Aortic root aneurysm and dissection", "Mitral valve prolapse", "Restrictive lung disease"]', 1, 'Aortic root dilation requires frequent monitoring with echocardiography.'),
    (v_topic_id, '26: A neonate presents with multiple fractures, blue sclerae, and hearing loss. What is the likely diagnosis?', '["Child abuse", "Osteogenesis Imperfecta", "Rickets", "Hypophosphatasia"]', 1, 'Type 1 OI is the most common form, caused by defects in Type I collagen.'),
    (v_topic_id, '27: Which syndrome is characterized by skin hyperextensibility, joint hypermobility, and easy bruising?', '["Marfan Syndrome", "Ehlers-Danlos Syndrome", "Osteogenesis Imperfecta", "Achondroplasia"]', 1, 'EDS is a group of connective tissue disorders with various inheritance patterns.'),
    (v_topic_id, '28: What is the most common cause of "achondroplasia"?', '["Maternal smoking", "Advanced paternal age (de novo mutation)", "Nutritional deficiency", "Teratogen exposure"]', 1, 'Most cases are new mutations in the FGFR3 gene, associated with older fathers.'),
    (v_topic_id, '29: A child with achondroplasia has "rhizomelic" shortening. What does this mean?', '["Shortening of the distal segments (hands/feet)", "Shortening of the proximal segments (humerus/femur)", "Shortening of the trunk", "Shortening of the neck"]', 1, 'Rhizomelic means proximal; mesomelic means middle; acromelic means distal.'),
    (v_topic_id, '30: A neonate has a small mandible (micrognathia), a posteriorly placed tongue (glossoptosis), and a U-shaped cleft palate. This is:', '["Pierre Robin sequence", "Potter sequence", "VACTERL association", "CHARGE syndrome"]', 0, 'A "sequence" is a single primary defect leading to a cascade of secondary anomalies.'),
    (v_topic_id, '31: Which "sequence" is caused by oligohydramnios leading to fetal compression, lung hypoplasia, and limb deformities?', '["Pierre Robin", "Potter", "VACTERL", "Pfeiffer"]', 1, 'Potter sequence can result from renal agenesis or posterior urethral valves.'),
    (v_topic_id, '32: What does the "V" stand for in VACTERL association?', '["Vascular", "Vertebral defects", "Vocal cord paralysis", "Visual loss"]', 1, 'VACTERL: Vertebral, Anal, Cardiac, Tracheo-Esophageal, Renal, Limb.'),
    (v_topic_id, '33: A neonate has Coloboma, Heart defects, Atresia choanae, Retarded growth, Genitourinary anomalies, and Ear anomalies. This is:', '["VACTERL", "CHARGE syndrome", "MURCS association", "PHACE syndrome"]', 1, 'CHARGE syndrome is often linked to mutations in the CHD7 gene.'),
    (v_topic_id, '34: What is the most common teratogen exposure worldwide causing intellectual disability?', '["Phenytoin", "Valproic acid", "Alcohol", "Mercury"]', 2, 'Fetal Alcohol Syndrome is the leading preventable cause of birth defects and ID.'),
    (v_topic_id, '35: Which facial features are characteristic of Fetal Alcohol Syndrome?', '["Large ears and long face", "Short palpebral fissures, smooth philtrum, and thin upper lip", "Cleft lip and palate", "Up-slanting eyes and epicanthal folds"]', 1, 'These three facial features are the diagnostic hallmarks.'),
    (v_topic_id, '36: A mother takes "Isotretinoin" (Accutane) during early pregnancy. What is the most likely fetal outcome?', '["Clear skin", "Severe CNS, cardiac, and craniofacial anomalies", "Limb reduction defects", "None"]', 1, 'Retinoic acid is a highly potent teratogen with a nearly 25% risk of major malformations.'),
    (v_topic_id, '37: Maternal use of "Valproic acid" is specifically associated with an increased risk of:', '["Neural tube defects (e.g., Spina Bifida)", "Clear cell adenocarcinoma of the vagina", "Ebstein anomaly", "Phocomelia"]', 0, 'Valproate interferes with folate metabolism.'),
    (v_topic_id, '38: Use of "Phenytoin" (Dilantin) during pregnancy can lead to "Fetal Hydantoin Syndrome," characterized by:', '["Short stature", "Hypoplastic nails and distal phalanges", "Webbed neck", "Blue sclerae"]', 1, 'Nail/digit hypoplasia is a classic finding.'),
    (v_topic_id, '39: A neonate is born with "Ebstein anomaly" (downward displacement of the tricuspid valve). Which maternal medication is likely?', '["Warfarin", "Lithium", "Tetracycline", "Fluoxetine"]', 1, 'Lithium exposure in the first trimester is a known (though small) risk factor.'),
    (v_topic_id, '40: Maternal use of "Warfarin" during the first trimester can cause:', '["Nasal hypoplasia and stippled epiphyses", "Fetal alcohol syndrome", "Grey baby syndrome", "Enamel hypoplasia"]', 0, 'Warfarin embryopathy resembles chondrodysplasia punctata.'),
    (v_topic_id, '41: A child is born with "phocomelia" (limbs attached directly to the trunk). This was classically caused by:', '["Tetracycline", "Thalidomide", "Cocaine", "Smoking"]', 1, 'Thalidomide was used for morning sickness in the 1950s-60s before its teratogenicity was known.'),
    (v_topic_id, '42: Which maternal infection is associated with the triad of "Cataracts, Deafness, and PDA"?', '["CMV", "Rubella", "Toxoplasmosis", "Syphilis"]', 1, 'Congenital Rubella Syndrome (CRS) classic triad.'),
    (v_topic_id, '43: A neonate has "snuffles" (bloody rhinitis), a desquamating rash on palms/soles, and hepatosplenomegaly. Likely infection?', '["Toxoplasmosis", "Syphilis", "CMV", "Parvovirus"]', 1, 'Congenital Syphilis also presents with "Hutchinson teeth" later in life.'),
    (v_topic_id, '44: What is the most common "innate error of metabolism" screened for in newborns?', '["Galactosemia", "Phenylketonuria (PKU)", "Maple Syrup Urine Disease", "Cystic Fibrosis"]', 1, 'PKU was the first disorder included in universal newborn screening.'),
    (v_topic_id, '45: A 3-day-old infant with a positive PKU screen should be placed on a diet restricted in:', '["Glucose", "Phenylalanine", "Tyrosine", "Valine"]', 1, 'Phenylalanine is an essential amino acid that cannot be metabolized into tyrosine in PKU.'),
    (v_topic_id, '46: An untreated child with PKU will often have which physical characteristic?', '["Dark skin and hair", "Fair skin, blue eyes, and a ''mousy'' body odor", "Obesity", "Port-wine stain"]', 1, 'Lack of tyrosine leads to reduced melanin production.'),
    (v_topic_id, '47: A neonate presents with jaundice, cataracts, and E. coli sepsis shortly after starting milk feeds. Diagnosis?', '["PKU", "Galactosemia", "Glycogen Storage Disease", "Biliary atresia"]', 1, 'Classical Galactosemia (GALT deficiency) is a medical emergency.'),
    (v_topic_id, '48: What is the immediate treatment for Galactosemia?', '["High-protein diet", "Stop all milk; use soy-based or lactose-free formula", "Liver transplant", "Phototherapy"]', 1, 'Elimination of galactose and lactose is essential to prevent liver failure and death.'),
    (v_topic_id, '49: A neonate''s diaper has a sweet, maple-syrup smell. What amino acids are elevated?', '["Phenylalanine", "Leucine, Isoleucine, Valine (Branched-chain)", "Glycine", "Methionine"]', 1, 'Maple Syrup Urine Disease (MSUD) involves a defect in branched-chain alpha-ketoacid dehydrogenase.'),
    (v_topic_id, '50: Which glycogen storage disease is characterized by severe fasting hypoglycemia, hepatomegaly, and doll-like facies?', '["Type I (Von Gierke)", "Type II (Pompe)", "Type III (Cori)", "Type V (McArdle)"]', 0, 'Von Gierke (Glucose-6-phosphatase deficiency) presents with lactic acidosis and hyperuricemia.'),
    (v_topic_id, '51: Which glycogen storage disease primarily affects the heart, causing massive cardiomegaly and early death?', '["Type I", "Type II (Pompe)", "Type IV", "Type VI"]', 1, 'Pompe disease is an acid maltase deficiency.'),
    (v_topic_id, '52: "Cherry-red spot" on the macula and severe startle reflex in a 6-month-old suggests:', '["Niemann-Pick Disease", "Tay-Sachs Disease", "Gaucher Disease", "Hurler Syndrome"]', 1, 'Tay-Sachs (Hexosaminidase A deficiency) does NOT have hepatosplenomegaly, unlike Niemann-Pick.'),
    (v_topic_id, '53: A child has coarse facial features, hepatosplenomegaly, corneal clouding, and developmental delay. This is:', '["Hunter Syndrome", "Hurler Syndrome", "Tay-Sachs", "Gaucher"]', 1, 'Hurler is a mucopolysaccharidosis (MPS I); Hunter (MPS II) has no corneal clouding.'),
    (v_topic_id, '54: Which finding distinguishes Niemann-Pick disease from Tay-Sachs disease?', '["Cherry-red spot", "Intellectual disability", "Hepatosplenomegaly", "Autosomal recessive inheritance"]', 2, 'Niemann-Pick (Sphingomyelinase deficiency) includes liver and spleen enlargement.'),
    (v_topic_id, '55: What is the gold standard for diagnosing a chromosomal abnormality like Down Syndrome?', '["Physical exam", "Quad screen", "Karyotype", "Ultrasound"]', 2, 'Karyotype provides definitive proof of the chromosomal arrangement.'),
    (v_topic_id, '56: A child has a "port-wine stain" in the V1/V2 distribution of the trigeminal nerve and seizures. Diagnosis?', '["Sturge-Weber Syndrome", "Neurofibromatosis Type 1", "Tuberous Sclerosis", "Von Hippel-Lindau"]', 0, 'Sturge-Weber is a phakomatosis with leptomeningeal angiomas.'),
    (v_topic_id, '57: Which neurocutaneous syndrome is characterized by "ash-leaf spots," facial angiofibromas, and "shagreen patches"?', '["Neurofibromatosis 1", "Neurofibromatosis 2", "Tuberous Sclerosis", "Ataxia-Telangiectasia"]', 2, 'TSC is associated with hamartomas in multiple organs (brain, heart, kidneys).'),
    (v_topic_id, '58: Cardiac "rhabdomyomas" in a neonate are highly suggestive of:', '["Down Syndrome", "Tuberous Sclerosis", "DiGeorge Syndrome", "Noonan Syndrome"]', 1, 'These often regress spontaneously but are a key diagnostic clue for TSC.'),
    (v_topic_id, '59: A child has >6 café-au-lait spots, axillary freckling (Lisch nodules), and optic gliomas. This is:', '["NF1 (von Recklinghausen disease)", "NF2", "Tuberous Sclerosis", "Sturge-Weber"]', 0, 'NF1 is caused by a mutation in the neurofibromin gene on chromosome 17.'),
    (v_topic_id, '60: Bilateral acoustic neuromas (vestibular schwannomas) are the hallmark of:', '["NF1", "NF2", "McCune-Albright Syndrome", "Tuberous Sclerosis"]', 1, 'NF2 is caused by a mutation on chromosome 22 (merlin gene).'),
    (v_topic_id, '61: A child has "precocious puberty," "large café-au-lait spots with irregular borders" (Coast of Maine), and "polyostotic fibrous dysplasia." Diagnosis?', '["NF1", "McCune-Albright Syndrome", "Albright Hereditary Osteodystrophy", "Noonan Syndrome"]', 1, 'Classic triad caused by a mosaic G-protein signaling mutation.'),
    (v_topic_id, '62: "Iniencephaly" is a severe neural tube defect involving:', '["The spinal cord only", "Retroflexion of the head with absence of the neck", "Protrusion of the brain through a skull defect", "Failure of the abdominal wall to close"]', 1, 'A rare and lethal neural tube defect.'),
    (v_topic_id, '63: What is the most common neural tube defect?', '["Anencephaly", "Spina Bifida Occulta", "Meningocele", "Myelomeningocele"]', 1, 'Occulta is often asymptomatic and found incidentally.'),
    (v_topic_id, '64: A neonate has a sac on the back containing meninges and spinal cord tissue. This is a:', '["Meningocele", "Myelomeningocele", "Encephalocele", "Lipoma"]', 1, 'Myelomeningocele is the most severe open neural tube defect.'),
    (v_topic_id, '65: Which intracranial malformation is almost always present in children with myelomeningocele?', '["Dandy-Walker malformation", "Chiari II malformation", "Holoprosencephaly", "Lissencephaly"]', 1, 'Downward displacement of the cerebellum and brainstem leads to obstructive hydrocephalus.'),
    (v_topic_id, '66: Supplementation with what nutrient before and during early pregnancy prevents 70% of neural tube defects?', '["Vitamin A", "Folic Acid", "Iron", "Vitamin B12"]', 1, '400 mcg/day for low-risk; 4 mg/day for high-risk (previous affected child).'),
    (v_topic_id, '67: A neonate has a "midline" defect where the brain fails to divide into two hemispheres. This is:', '["Lissencephaly", "Holoprosencephaly", "Schizencephaly", "Hydranencephaly"]', 1, 'Often associated with Trisomy 13 and sonic hedgehog gene mutations.'),
    (v_topic_id, '68: Failure of the "abdominal wall" to close, resulting in bowel herniation to the "right" of the umbilicus without a sac, is:', '["Omphalocele", "Gastroschisis", "Umbilical hernia", "Diaphragmatic hernia"]', 1, 'Gastroschisis is not usually associated with other syndromes, unlike omphalocele.'),
    (v_topic_id, '69: A midline abdominal wall defect where bowel and sometimes liver are covered by a "peritoneal sac" is:', '["Omphalocele", "Gastroschisis", "Inguinal hernia", "Ectopia cordis"]', 0, 'Omphalocele is frequently associated with Trisomy 18 and Beckwith-Wiedemann.'),
    (v_topic_id, '70: A "scaphoid abdomen" and respiratory distress in a neonate suggest:', '["Gastroschisis", "Congenital Diaphragmatic Hernia (CDH)", "Pyloric stenosis", "Tracheoesophageal fistula"]', 1, 'Abdominal contents move into the chest, usually on the left (Bochdalek hernia).'),
    (v_topic_id, '71: What is the primary cause of death in infants with Congenital Diaphragmatic Hernia?', '["Sepsis", "Pulmonary hypoplasia and hypertension", "Heart failure", "Malnutrition"]', 1, 'The lungs fail to develop because space is occupied by abdominal organs.'),
    (v_topic_id, '72: A neonate with "excessive drooling" and choking during the first feed likely has:', '["Pyloric stenosis", "Esophageal atresia with Tracheoesophageal fistula (TEF)", "Duodenal atresia", "Gastroesophageal reflux"]', 1, 'Classically presents with the inability to pass a nasogastric tube.'),
    (v_topic_id, '73: What is the most common type of Tracheoesophageal Fistula?', '["Pure esophageal atresia", "H-type fistula", "Esophageal atresia with distal TEF", "Esophageal atresia with proximal TEF"]', 2, 'Type C (distal fistula) accounts for ~85% of cases.'),
    (v_topic_id, '74: "Double bubble" sign on abdominal X-ray is classic for:', '["Pyloric stenosis", "Duodenal atresia", "Midgut volvulus", "Intussusception"]', 1, 'Highly associated with Down Syndrome.'),
    (v_topic_id, '75: A "triple bubble" sign on X-ray suggests:', '["Duodenal atresia", "Jejunal atresia", "Ileal atresia", "Meconium ileus"]', 1, 'Jejunal atresia is often due to a vascular accident in utero.'),
    (v_topic_id, '76: Failure to pass meconium within 48 hours and a "squirt sign" on rectal exam suggests:', '["Hirschsprung Disease", "Meconium ileus", "Imperforate anus", "Anal stenosis"]', 0, 'Absence of ganglion cells in the distal colon.'),
    (v_topic_id, '77: "Meconium ileus" is highly suggestive of which underlying condition?', '["Down Syndrome", "Cystic Fibrosis", "Hirschsprung Disease", "Celiac Disease"]', 1, 'Thick, inspissated meconium obstructs the distal ileum.'),
    (v_topic_id, '78: A "port-wine stain" on the leg that is associated with "limb overgrowth" suggests:', '["Sturge-Weber Syndrome", "Klippel-Trenaunay Syndrome", "NF1", "Proteus Syndrome"]', 1, 'Classic triad: port-wine stain, venous malformations, and soft tissue/bony hypertrophy.'),
    (v_topic_id, '79: Which defect is characterized by an "open urinary bladder" on the lower abdominal wall?', '["Bladder exstrophy", "Epispadias", "Hypospadias", "Prune belly syndrome"]', 0, 'Part of the epispadias-exstrophy complex.'),
    (v_topic_id, '80: "Prune belly syndrome" (Eagle-Barrett) consists of:', '["Abdominal muscle deficiency, urinary tract anomalies, and undescended testes", "Obesity and hunger", "Macroglossia", "Limb defects"]', 0, 'Classically seen in males.'),
    (v_topic_id, '81: "Hypospadias" is a condition where the urethral meatus is located on the:', '["Dorsal surface of the penis", "Ventral surface of the penis", "Scrotum only", "Perineum only"]', 1, 'Circumcision should be avoided as the foreskin may be needed for surgical repair.'),
    (v_topic_id, '82: "Epispadias" is a condition where the urethral meatus is on the:', '["Ventral surface", "Dorsal surface", "Tip", "Side"]', 1, 'Often associated with bladder exstrophy.'),
    (v_topic_id, '83: A neonate with "bilateral renal agenesis" will have what feature at birth?', '["Large kidneys", "Potter facies and severe respiratory distress", "Polyuria", "Anasarca"]', 1, 'Lack of urine production leads to oligohydramnios and lung hypoplasia.'),
    (v_topic_id, '84: What is the most common cause of "ambiguous genitalia" in a phenotypically female infant (46,XX)?', '["Androgen Insensitivity Syndrome", "Congenital Adrenal Hyperplasia (CAH)", "Turner Syndrome", "Klinefelter Syndrome"]', 1, '21-hydroxylase deficiency is the most common form, leading to virilization.'),
    (v_topic_id, '85: A neonate with CAH is at risk for what life-threatening complication in the first weeks of life?', '["Hypertension", "Salt-wasting crisis (hyponatremia, hyperkalemia, shock)", "Hypokalemia", "Hypernatremia"]', 1, 'Lack of aldosterone leads to severe electrolyte imbalances.'),
    (v_topic_id, '86: Phenotypic male (46,XY) with female external genitalia and a short, blind-ending vagina likely has:', '["CAH", "Complete Androgen Insensitivity Syndrome (CAIS)", "5-alpha-reductase deficiency", "Klinefelter Syndrome"]', 1, 'The body cannot respond to testosterone; testes are usually intra-abdominal.'),
    (v_topic_id, '87: Which condition presents at puberty as a "girl who turns into a boy" (virilization of a previously female-appearing child)?', '["CAIS", "5-alpha-reductase deficiency", "Turner Syndrome", "Noonan Syndrome"]', 1, 'Inability to convert testosterone to DHT in utero, but puberty-related testosterone surge causes virilization.'),
    (v_topic_id, '88: A neonate has a "holosystolic murmur" at the left lower sternal border. Diagnosis?', '["ASD", "VSD", "PDA", "Coarctation"]', 1, 'VSD is the most common congenital heart disease overall.'),
    (v_topic_id, '89: "Machine-like" continuous murmur at the left infraclavicular area suggests:', '["VSD", "PDA (Patent Ductus Arteriosus)", "Aortic stenosis", "Tricuspid atresia"]', 1, 'Common in premature infants and those with congenital rubella.'),
    (v_topic_id, '90: Which congenital heart disease is characterized by "boot-shaped heart" on X-ray?', '["Transposition of Great Arteries", "Tetralogy of Fallot", "Ebstein Anomaly", "Hypoplastic Left Heart"]', 1, 'The "boot" is caused by right ventricular hypertrophy and a narrow pulmonary waist.'),
    (v_topic_id, '91: "Egg-on-a-string" heart on X-ray is classic for:', '["Tetralogy of Fallot", "Transposition of the Great Arteries (TGA)", "TAPVR", "Truncus Arteriosus"]', 1, 'The narrow mediastinum is due to the anterior-posterior relationship of the great vessels.'),
    (v_topic_id, '92: "Snowman" or "Figure 8" heart on X-ray suggests:', '["TGA", "Total Anomalous Pulmonary Venous Return (TAPVR)", "VSD", "Ebstein Anomaly"]', 1, 'The supracardiac shadow is formed by the anomalous veins.'),
    (v_topic_id, '93: Which congenital heart disease presents with "cyanosis" immediately at birth and is a medical emergency?', '["VSD", "TGA", "ASD", "Pulmonic stenosis"]', 1, 'TGA is the most common cyanotic lesion presenting in the first 24 hours.'),
    (v_topic_id, '94: Prostaglandin E1 (Alprostadil) is given to a neonate with cyanotic heart disease to:', '["Close the ductus arteriosus", "Keep the ductus arteriosus open", "Lower blood pressure", "Treat infection"]', 1, 'Maintenance of ductal patency is life-saving in "ductal-dependent" lesions.'),
